export type CheckStatus = "pass" | "fail";

export interface CheckResult {
  name: string;
  status: CheckStatus;
  critical: boolean;
  latencyMs: number;
  error?: string;
}

export interface DependencyCheck {
  name: string;
  critical: boolean;
  run(signal: AbortSignal): Promise<void>;
}

export async function runCheck(check: DependencyCheck, timeoutMs: number): Promise<CheckResult> {
  const controller = new AbortController();
  const started = Date.now();
  let timer: NodeJS.Timeout | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      controller.abort();
      reject(new Error(`timed out after ${timeoutMs}ms`));
    }, timeoutMs);
  });

  try {
    await Promise.race([check.run(controller.signal), timeout]);
    return { name: check.name, status: "pass", critical: check.critical, latencyMs: Date.now() - started };
  } catch (err) {
    return {
      name: check.name,
      status: "fail",
      critical: check.critical,
      latencyMs: Date.now() - started,
      error: (err as Error).message,
    };
  } finally {
    clearTimeout(timer);
  }
}

import { CheckResult, DependencyCheck, runCheck } from "./checks";

export interface HealthResponse {
  status: number;
  body: { status: string; checks?: CheckResult[]; checkedAt?: string };
}

export interface HealthOptions {
  checkTimeoutMs: number;
  cacheMs: number;
}

export class HealthService {
  private cached: { results: CheckResult[]; at: number } | null = null;
  private inflight: Promise<CheckResult[]> | null = null;
  private shuttingDown = false;

  constructor(
    private readonly checks: DependencyCheck[],
    private readonly opts: HealthOptions,
    private readonly now: () => number = Date.now,
  ) {}

  markShuttingDown(): void {
    this.shuttingDown = true;
  }

  liveness(): HealthResponse {
    return { status: 200, body: { status: "alive" } };
  }

  async readiness(): Promise<HealthResponse> {
    if (this.shuttingDown) {
      return { status: 503, body: { status: "shutting_down" } };
    }

    const results = await this.currentResults();
    const criticalDown = results.some((r) => r.critical && r.status === "fail");
    const degraded = results.some((r) => !r.critical && r.status === "fail");

    return {
      status: criticalDown ? 503 : 200,
      body: {
        status: criticalDown ? "unavailable" : degraded ? "degraded" : "ok",
        checks: results,
        checkedAt: new Date(this.cached?.at ?? this.now()).toISOString(),
      },
    };
  }

  private async currentResults(): Promise<CheckResult[]> {
    if (this.cached && this.now() - this.cached.at < this.opts.cacheMs) {
      return this.cached.results;
    }
    if (!this.inflight) {
      this.inflight = Promise.all(this.checks.map((c) => runCheck(c, this.opts.checkTimeoutMs)))
        .then((results) => {
          this.cached = { results, at: this.now() };
          return results;
        })
        .finally(() => {
          this.inflight = null;
        });
    }
    return this.inflight;
  }
}

import http from "node:http";
import { HealthService } from "./healthService";
import { DependencyCheck } from "./checks";

export interface Pinger {
  ping(signal: AbortSignal): Promise<void>;
}

export function buildChecks(clickhouse: Pinger, kafka: Pinger, geoIpCache: Pinger): DependencyCheck[] {
  return [
    { name: "clickhouse", critical: true, run: (s) => clickhouse.ping(s) },
    { name: "kafka_producer", critical: true, run: (s) => kafka.ping(s) },
    { name: "geoip_cache", critical: false, run: (s) => geoIpCache.ping(s) },
  ];
}

export function startHealthServer(health: HealthService, port: number): http.Server {
  const server = http.createServer(async (req, res) => {
    let result;
    if (req.url === "/healthz/live") {
      result = health.liveness();
    } else if (req.url === "/healthz/ready") {
      result = await health.readiness();
    } else {
      res.writeHead(404).end();
      return;
    }
    res.writeHead(result.status, { "content-type": "application/json", "cache-control": "no-store" });
    res.end(JSON.stringify(result.body));
  });

  process.once("SIGTERM", () => {
    health.markShuttingDown();
  });

  return server.listen(port);
}
